diff --git a/tests/test_version_req.rs b/tests/test_version_req.rs
index f3e4d80..93cfa66 100644
--- a/tests/test_version_req.rs
+++ b/tests/test_version_req.rs
@@ -478,3 +478,27 @@ fn test_wildcard_and_another() {
         "wildcard req (*) must be the only comparator in the version req",
     );
 }
+
+#[test]
+fn test_caret_minor_only() {
+    // Caret without patch: ^I.J means ^I.J.0 = >=I.J.0, <(I+1).0.0 (or <0.1.0 when I=0 and J>0)
+    // or =0.(J+1).0 when both I=0 and J=0
+
+    let ref r = req("^1.2");
+    assert_match_all(r, &["1.2.0", "1.3.5", "1.99.99"]);
+    assert_match_none(r, &["1.1.9", "2.0.0", "0.2.0"]);
+
+    let ref r = req("^0.2");
+    assert_match_all(r, &["0.2.0", "0.2.5"]);
+    assert_match_none(r, &["0.1.9", "0.3.0", "1.0.0"]);
+
+    // ^5.6 with major=0 and minor > 0 means patch is implicitly 0: >=5.6.0 <6.0.0
+    let ref r = req("^5");
+    assert_match_all(r, &["5.0.0", "5.1.0", "5.99.99"]);
+    assert_match_none(r, &["4.99.99", "6.0.0"]);
+
+    // Pre-release: ^1.2 should match 1.2.x-pre if 1.2 is also in range
+    let ref r = req("^1.2");
+    assert_match_all(r, &["1.2.0-alpha", "1.3.0-beta"]);
+    assert_match_none(r, &["1.2.0"]); // no pre-release on comparator, so 1.2.0 should also match (it's not pre-release)
+}
